  afterEach(cleanup);

  it('merges className/handlers onto the slotted element while keeping siblings', () => {
    const handleClick = vi.fn();
    render(
      <Slot className="slot" onClick={handleClick}>
        <span data-icon-left>left</span>
        <Slottable>
          <a className="child" href="/">
            link
          </a>
